-- Durable supplier mutation journal.
-- One logical outbound mutation per tenant, booking, operation and idempotency key.
-- PREPARED means the supplier was not called. SENDING and UNKNOWN mean it may have been.
-- The supplier reference is stored here before the booking row or audit event is updated.
-- No guest PII, credentials, or raw supplier payloads are stored.
--
-- Tenant indexes: (tenant_id, status) for reconciliation, (tenant_id, booking_id) for
-- booking recovery, (tenant_id, hold_id) for hold-expiry protection.
--
-- Rollback is a later forward migration. Do not edit this file after it is applied.
--   DROP POLICY IF EXISTS "SupplierMutation_tenant_isolation" ON "SupplierMutation";
--   DROP TABLE IF EXISTS "SupplierMutation";
--   DROP TYPE IF EXISTS "SupplierMutationStatus";
--   DROP TYPE IF EXISTS "SupplierMutationOperation";

-- CreateEnum
CREATE TYPE "SupplierMutationOperation" AS ENUM ('PREBOOK', 'BOOK', 'CANCEL');

-- CreateEnum
CREATE TYPE "SupplierMutationStatus" AS ENUM ('PREPARED', 'SENDING', 'ACKNOWLEDGED', 'REJECTED', 'UNKNOWN', 'RESOLVED');

-- CreateTable
CREATE TABLE "SupplierMutation" (
    "id" TEXT NOT NULL,
    "tenant_id" TEXT NOT NULL,
    "booking_id" TEXT NOT NULL,
    "hold_id" TEXT NOT NULL,
    "supplier_key" TEXT NOT NULL,
    "operation" "SupplierMutationOperation" NOT NULL,
    "idempotency_key" TEXT NOT NULL,
    "request_id" TEXT NOT NULL,
    "status" "SupplierMutationStatus" NOT NULL,
    "attempted_at" TIMESTAMP(3),
    "acknowledged_at" TIMESTAMP(3),
    "resolved_at" TIMESTAMP(3),
    "supplier_reference" TEXT,
    "supplier_status" TEXT,
    "request_fingerprint" TEXT NOT NULL,
    "failure_category" TEXT,
    "failure_code" TEXT,
    "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMP(3) NOT NULL,

    CONSTRAINT "SupplierMutation_pkey" PRIMARY KEY ("id")
);

-- CreateIndex
CREATE INDEX "SupplierMutation_tenant_id_status_idx" ON "SupplierMutation"("tenant_id", "status");

-- CreateIndex
CREATE INDEX "SupplierMutation_tenant_id_booking_id_idx" ON "SupplierMutation"("tenant_id", "booking_id");

-- CreateIndex
CREATE INDEX "SupplierMutation_tenant_id_hold_id_idx" ON "SupplierMutation"("tenant_id", "hold_id");

-- CreateIndex
CREATE UNIQUE INDEX "SupplierMutation_tenant_id_booking_id_operation_idempotency_key" ON "SupplierMutation"("tenant_id", "booking_id", "operation", "idempotency_key");

-- AddForeignKey
ALTER TABLE "SupplierMutation" ADD CONSTRAINT "SupplierMutation_tenant_id_fkey" FOREIGN KEY ("tenant_id") REFERENCES "tenants"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "SupplierMutation" ADD CONSTRAINT "SupplierMutation_booking_id_fkey" FOREIGN KEY ("booking_id") REFERENCES "Booking"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "SupplierMutation" ADD CONSTRAINT "SupplierMutation_tenant_id_hold_id_fkey" FOREIGN KEY ("tenant_id", "hold_id") REFERENCES "InventoryHold"("tenant_id", "id") ON DELETE RESTRICT ON UPDATE CASCADE;

ALTER TABLE "SupplierMutation" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "SupplierMutation" FORCE ROW LEVEL SECURITY;
CREATE POLICY "SupplierMutation_tenant_isolation" ON "SupplierMutation"
  USING ("tenant_id" = "fbeds_current_tenant_id"())
  WITH CHECK ("tenant_id" = "fbeds_current_tenant_id"());

DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'fbeds_api') THEN
    EXECUTE 'GRANT SELECT, INSERT, UPDATE ON "SupplierMutation" TO fbeds_api';
  END IF;
END $$;
